-- Generated by scripts/build-major-party-officer-expansion.py from reviewed official party sources.
ALTER TABLE person_party_affiliations
    ADD COLUMN IF NOT EXISTS role_tier TEXT NOT NULL DEFAULT 'primary';

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'person_party_affiliations_role_tier_check'
    ) THEN
        ALTER TABLE person_party_affiliations
            ADD CONSTRAINT person_party_affiliations_role_tier_check
            CHECK (role_tier IN ('primary', 'secondary', 'committee'));
    END IF;
END $$;

UPDATE person_party_affiliations
SET role_tier = 'secondary', updated_at = NOW()
WHERE role_context = 'party_officer'
  AND REPLACE(normalized_party, '臺', '台') = '台灣民眾黨'
  AND (
      COALESCE(display_order, 0) >= 100
      OR role_title LIKE '%中央委員%'
      OR role_title LIKE '%中央評議委員%'
  );

